#pragma once

// The kit: glyder's library of low-polygon models, shared by every Gygax simulation, the VR client,
// the desktop viewer and (as glTF) the web viewers.
//
// Every model is generated by code from a handful of primitives (lofts, lathes, wings, boxes), flat
// shaded, at real-world size in metres, in the FLU model frame (x forward, y left, z up, origin at the
// centre of mass or on the ground for ground units). Colour lives in the vertices; the alpha byte
// carries a material code so one instanced draw can tint a model in its team colour and light its
// emitters, with no textures at all.

#include <cstdint>
#include <span>
#include <string_view>
#include <vector>

#include <glyder/math.hpp>

namespace glyder::kit {

enum class Material : std::uint8_t {
    Matte = 0,        // lit vertex colour
    Team = 1,         // lit, vertex colour replaced by the instance's team colour
    Emissive = 2,     // self-lit vertex colour: lenses, exhausts, windows, lamps
    TeamEmissive = 3, // self-lit team colour: nav and identification lights
};

struct Vertex {
    float px, py, pz;
    std::int8_t nx, ny, nz, pad; // unit normal, snorm8
    std::uint8_t r, g, b, a;     // sRGB colour; a = material code * 64
};
static_assert(sizeof(Vertex) == 20);

struct Bounds {
    Vec3 min{1e30f, 1e30f, 1e30f}, max{-1e30f, -1e30f, -1e30f};
    [[nodiscard]] Vec3 centre() const { return (min + max) * 0.5f; }
    [[nodiscard]] Vec3 size() const { return max - min; }
    [[nodiscard]] float radius() const { return length(size()) * 0.5f; }
};

struct Mesh {
    std::vector<Vertex> vertices;
    std::vector<std::uint32_t> indices;
    Bounds bounds;
    [[nodiscard]] std::size_t triangles() const { return indices.size() / 3; }
};

// Every shape in the kit. The order is the wire order: append only.
enum class Shape : std::uint16_t {
    // Air
    Kite,        // OHFLOCK's flying wing: 1.6 m, RGB laser turret
    Quadcopter,  // small multirotor, 0.55 m
    FixedWing,   // 3 m survey UAV, V-tail, pusher
    Fighter,     // twin-tail fighter, 15 m
    Striker,     // attack jet with underwing stores, 14 m
    Helicopter,  // utility helicopter, 13 m
    Interceptor, // wargames' delta drone, 2.4 m
    Missile,     // 3 m air-to-air or surface-to-air missile
    Bomb,        // guided bomb, 2.5 m
    // Space
    RelaySat,   // flat-panel LEO relay, solar wings
    ImagingSat, // telescope bus, solar wings
    // Ground
    Truck,         // 6x6 cargo truck, the convoy
    Tank,          // main battle tank
    Apc,           // 8x8 armoured carrier
    SamLauncher,   // launcher vehicle with a four-tube box
    AaaGun,        // twin-barrel gun on a platform
    Radar,         // trailer radar with a planar array
    AcousticArray, // mast with a ring of microphones
    Jammer,        // van with an antenna mast
    Rover,         // six-wheel rocker-bogie robot
    RobotArm,      // six-axis arm on a pedestal
    Bunker,        // wargames' command bunker
    Turret,        // wargames' ground turret
    // Wargames' hive
    Swarmer,
    Bruiser,
    Spitter,
    // Sea
    Boat,
    Buoy,
    // Structures and scenery
    GroundStation,
    Tower,
    Building,
    Tree,
    Palm,
    Rock,
    Crate,
    // Glyphs
    Marker,   // waypoint gem
    Node,     // a Gygax compute node: a monolith with lit seams
    Operator, // a glyder user's presence: head and visor
    Wand,     // a hand controller as glyder draws it
    // Later additions (appended, so earlier shapes keep their wire numbers)
    Microdrone, // insect-like recon drone, 0.13 m
    Quadruped,  // legged robot, 1.1 m, with a microdrone dock on its back
    Megadrone,  // elephant-sized legged robot with a lifting fork and work lights, 6.6 m
    Hypersonic, // lifting-body carrier that delivers the flock, 30 m
    Person,     // a standing figure, 1.8 m
    Cup,        // a drink of water, 0.12 m
    Pod,        // a braked drop pod, 2.4 m
    Slab,       // a 4 x 3 m section of concrete floor, 0.35 m thick, with rebar ends
    Count
};

[[nodiscard]] std::string_view name(Shape s);
[[nodiscard]] Shape shapeFromName(std::string_view n, Shape fallback = Shape::Marker);
[[nodiscard]] std::span<const Shape> allShapes();
[[nodiscard]] Mesh build(Shape s);

// What kind of thing a shape is, for camera framing, icon scale and drop-in cockpit placement.
enum class Domain : std::uint8_t { Air, Space, Ground, Sea, Structure, Glyph };
[[nodiscard]] Domain domain(Shape s);
// Where a pilot's eye sits in the model frame when dropped in.
[[nodiscard]] Vec3 eyepoint(Shape s);

// The palette (sRGB). Muted bodies so the team colours and emitters read at a glance.
namespace palette {
inline constexpr Rgb8 graphite = hex(0x2B2F36), gunmetal = hex(0x434A54), steel = hex(0x6B7480), ash = hex(0x9AA3AD), bone = hex(0xE6E1D3),
                      sand = hex(0xC9B48A), dune = hex(0xB89A6A), olive = hex(0x5F6B45), khaki = hex(0x8C8058), rubber = hex(0x1D1F22),
                      glass = hex(0x14222E), gold = hex(0xC9A646), cell = hex(0x1F3B73), copper = hex(0xB87333), white = hex(0xF2F2EE),
                      bark = hex(0x5A4632), leaf = hex(0x3F6B3A), frond = hex(0x5C8A3A), basalt = hex(0x6E655A), hive = hex(0x4A2D5C),
                      chitin = hex(0x2E1F38), sea = hex(0x1E4E66);
inline constexpr Rgb8 engine = hex(0xFF8A2B), lamp = hex(0xFFE7B0), laserR = hex(0xFF2A3A), laserG = hex(0x2BFF6A), laserB = hex(0x3A7BFF),
                      acid = hex(0x9BFF3A), navRed = hex(0xFF3030), navGreen = hex(0x30FF60), seam = hex(0x59F2FF);
// Team colours, by the wire's team byte.
inline constexpr Rgb8 teams[8] = {hex(0xE6E1D3), hex(0x2EE6D6), hex(0xFF5A36), hex(0xFFB000),
                                  hex(0x9BFF3A), hex(0xB59CFF), hex(0xFFD54A), hex(0xFF6FD8)};
} // namespace palette

// Builds meshes from primitives under a transform stack. Triangles are flat shaded and wound so
// their normals face away from the solid, whatever order the caller supplies points in.
class Builder {
public:
    Builder& color(Rgb8 c, Material m = Material::Matte) {
        colour_ = c;
        material_ = m;
        return *this;
    }
    Builder& team() { return color(palette::bone, Material::Team); }
    void push(const Mat4& m);
    void pop();
    template <class F> void at(Vec3 t, Quat q, F&& f) {
        push(compose(t, q));
        f();
        pop();
    }
    // Run f twice: as authored and mirrored across the x-z plane (left and right sides).
    template <class F> void mirrored(F&& f) {
        f();
        push(scaling({1, -1, 1}));
        f();
        pop();
    }

    // A triangle and a quad; `inside` is a point inside the solid, used to orient the face.
    void tri(Vec3 a, Vec3 b, Vec3 c, Vec3 inside);
    void quad(Vec3 a, Vec3 b, Vec3 c, Vec3 d, Vec3 inside);
    // A double-sided thin panel (solar wing, rotor disc, fin).
    void panel(Vec3 a, Vec3 b, Vec3 c, Vec3 d);

    void box(Vec3 centre, Vec3 size);
    // A box whose top face is inset: chamfered hulls, cabs, turrets.
    void wedgeBox(Vec3 centre, Vec3 size, float topInsetX, float topInsetY, float topShiftX = 0);
    // Connect rings of equal point count into a hull, optionally capping both ends.
    void loft(std::span<const std::vector<Vec3>> rings, bool capStart = true, bool capEnd = true);
    // A solid of revolution about the x axis from (x, radius) pairs.
    void lathe(std::span<const Vec2> profile, int segments, float rollOffset = 0);
    // A cylinder between two points.
    void cylinder(Vec3 a, Vec3 b, float radius, int segments, bool caps = true);
    void cone(Vec3 base, Vec3 tip, float radius, int segments);
    // A tapered aerofoil from root to tip (both leading-edge points), chords along -x.
    void wing(Vec3 rootLe, float rootChord, Vec3 tipLe, float tipChord, float thickness);
    void icosphere(Vec3 centre, float radius, int subdivisions, float jitter = 0, std::uint32_t seed = 1);
    // A wheel or road wheel with a hub, axle along y.
    void wheel(Vec3 centre, float radius, float width, int segments = 10);

    [[nodiscard]] Mesh finish();

private:
    void emit(Vec3 a, Vec3 b, Vec3 c);
    std::vector<Vertex> v_;
    std::vector<Mat4> stack_{Mat4::identity()};
    Rgb8 colour_{palette::ash};
    Material material_{Material::Matte};
};

// A chamfered elliptical cross-section ring at x: half-width w, half-height h, centre height z.
[[nodiscard]] std::vector<Vec3> ring(float x, float w, float h, float z = 0, int points = 8, float squareness = 0.35f);

// Terrain: a heightfield as a flat-shaded, low-polygon surface in the world frame (ENU metres), with
// sand-to-rock colouring by slope and height. `step` decimates (every `step`-th sample).
struct HeightSamples {
    int w{0}, h{0};
    float cell{1}, x0{0}, y0{0};
    const float* z{nullptr};
};
// With `clipRadius` > 0 only a disc of that radius around (cx, cy) is kept, darkening toward its rim:
// a round map table rather than a square slab.
[[nodiscard]] Mesh terrain(const HeightSamples& f, int step = 1, float clipRadius = 0, float cx = 0, float cy = 0);

// The whole kit as one glTF 2.0 binary (.glb): one mesh per shape, vertex colours, a material per
// code. Lets the HTML viewers and any DCC tool use exactly the same models.
[[nodiscard]] std::vector<std::uint8_t> exportGlb();

} // namespace glyder::kit
